// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"altcoin":{"slug":"altcoin","cat":"basics","en":"Altcoin","contentLocale":"tr","term":"Altcoin","aka":["alt coin","altlar"],"short":"Altcoin, Bitcoin dışındaki tüm kripto paralar için kullanılan genel bir terimdir; Ethereum ve Solana gibi büyük ağlardan küçük proje token'larına ve memecoin'lere kadar geniş bir yelpazeyi kapsar.","body":[["Kelime alternative coin ifadesinden gelir. Bazı yatırımcılar ",["ETH","ethereum"],"'yi ayrı tutup yalnızca daha küçük coinlere altcoin der; ama en yaygın kullanım ",["Bitcoin","bitcoin"]," dışındaki her şeydir. ",["Stablecoin","stablecoin"],"'ler teknik olarak bu gruba girse de çoğu zaman ayrı bir kategori olarak ele alınır."],["Altcoin'ler genellikle Bitcoin'den daha oynaktır. ",["Piyasa değeri","market-capitalization"]," küçük olan bir coinde görece küçük alım satımlar bile fiyatı sert hareket ettirebilir. Likiditesi düşük coinlerde ",["alış-satış makası","bid-ask-spread"]," geniş, ",["kayma","slippage"]," yüksek olabilir."],"Bir altcoin'i değerlendirirken projenin ne yaptığına, token ekonomisine, dolaşımdaki arza, ileride açılacak kilitli token'lara ve hangi borsalarda ne kadar hacimle işlem gördüğüne bakmak işe yarar. Popülerlik tek başına sağlam bir ölçüt değildir."],"example":"Portföyünüzde 1.000 USDT'lik BTC ve 1.000 USDT'lik küçük bir altcoin olduğunu varsayalım. Piyasa genelinde bir düşüşte BTC yüzde 10 gerilerse BTC kısmı 900 USDT'ye iner. Aynı gün altcoin yüzde 30 düşerse o kısım 700 USDT'ye geriler. Toplam portföy 2.000 USDT'den 1.600 USDT'ye iner ve kaybın 300 USDT'si altcoin'den gelir. Yükselişte de tablo tersine dönebilir; altcoin'lerin hareketleri her iki yönde de genellikle daha serttir.","mistakes":["Birim fiyatı düşük olan bir altcoin'i ucuz sanmak; asıl bakılması gereken piyasa değeridir.","Hacmi çok düşük bir altcoin'e büyük piyasa emriyle girip yüksek kaymaya uğramak.","Altcoin sezonu beklentisiyle tüm portföyü küçük coinlere yığmak."],"faq":[{"q":"Ethereum bir altcoin mi?","a":"Geniş tanımla evet, çünkü Bitcoin değildir. Ancak büyüklüğü nedeniyle birçok yatırımcı ETH'yi ayrı bir kategori olarak görür."},{"q":"Altcoin sezonu ne demek?","a":"Altcoin'lerin bir dönem boyunca Bitcoin'den daha iyi performans gösterdiği piyasa evresine verilen gayriresmî bir addır. Ne zaman başlayıp biteceği önceden bilinemez."}],"title":"Altcoin nedir? Bitcoin dışındaki kripto paralar","description":"Altcoin'in ne demek olduğunu, neden Bitcoin'den daha oynak olduğunu ve bir altcoin'i değerlendirirken nelere bakmanız gerektiğini öğrenin.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC), 2009'da Satoshi Nakamoto takma adıyla başlatılan, iş ispatı ile çalışan ve toplam arzı 21 milyon BTC ile sınırlı olan ilk ve piyasa değeri en büyük kripto paradır."],["memecoin","Memecoin","Memecoin, bir internet şakası, hayvan figürü veya popüler kültür öğesinden ilham alan, değeri büyük ölçüde topluluk ilgisine ve spekülasyona dayanan bir kripto paradır; Dogecoin ve Shiba Inu en bilinen örneklerdir."],["market-capitalization","Piyasa değeri (market cap)","Piyasa değeri (market cap), bir kripto paranın güncel fiyatının dolaşımdaki arzla çarpılmasıyla bulunan toplam değerdir ve coinlerin büyüklüğünü karşılaştırmak için kullanılır."],["token-listing","Token listelemesi","Token listelemesi, bir kripto varlığın bir borsada işlem çiftleriyle alınıp satılabilir hâle getirilmesi, yani borsanın o token için yatırma, çekim ve işlem hizmeti açmasıdır."],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir."]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":"/coins","cta":false},"layer-2":{"slug":"layer-2","cat":"basics","en":"Layer 2 (L2)","contentLocale":"tr","term":"Katman 2 (Layer 2, L2)","aka":["L2","layer 2","katman 2 ağı","rollup"],"short":"Katman 2 (Layer 2, L2), işlemleri ana blockchain'in dışında daha hızlı ve ucuz şekilde işleyip sonuçlarını bir Layer 1'e (çoğu zaman Ethereum'a) kaydeden ölçekleme ağıdır.","body":[["En yaygın L2 türü rollup'tır. Rollup'lar yüzlerce işlemi toplayıp sıkıştırır ve tek bir paket halinde ",["Ethereum","ethereum"],"'a yazar. Böylece L1 gas maliyeti çok sayıda kullanıcı arasında paylaşılır ve işlem başına ücret düşer."],"Optimistic rollup'lar (Arbitrum, Optimism, Base) işlemlerin doğru olduğunu varsayar ve bir itiraz süresi tanır; bu yüzden resmi köprüyle L1'e çekim yaklaşık bir hafta sürebilir. ZK rollup'lar (zkSync, Starknet, Linea gibi) geçerlilik kanıtı kullanır ve kesinleşme daha hızlı olabilir.","L2'ler L1'in güvenliğinden yararlansa da kendi riskleri vardır: işlemleri sıralayan sequencer'ın merkezi olması, yükseltme yetkileri ve köprü kontratları bunlardan bazılarıdır. Borsadan çekim yaparken doğru L2 ağını seçmek ve alıcı cüzdanın o ağı desteklediğinden emin olmak gerekir."],"example":["Ethereum ana ağında bir token takası için 180.000 gas gerektiğini ve gas fiyatının 20 gwei olduğunu varsayalım. Ücret 180.000 x 20 = 3.600.000 gwei, yani 0,0036 ETH eder; ETH 2.800 ",["USDT","usdt"]," iken bu yaklaşık 10 USDT'dir. Aynı takası Arbitrum gibi bir L2'de yaptığınızda ücret 0,05 USDT civarında olabilir. Ayda 20 takas yapan biri için fark kabaca 200 USDT'ye karşı 1 USDT demektir."],"mistakes":["Borsadan çekim yaparken Ethereum yerine L2 ağını, ya da tersini yanlışlıkla seçmek.","Resmi köprüyle L2'den L1'e çekimin anında olacağını sanmak; optimistic rollup'larda bekleme süresi vardır.","L2'de işlem yapmak için de o ağda gas ödeyecek ETH bulundurmanız gerektiğini unutmak."],"faq":[{"q":"Layer 2 ağları güvenli mi?","a":"L2'ler sonuçlarını Ethereum'a kaydettiği için L1 güvenliğinden yararlanır, ancak sequencer, yükseltme yetkileri ve köprüler ek riskler taşır. Her L2'nin olgunluk düzeyi farklıdır."},{"q":"En bilinen Ethereum L2'leri hangileri?","a":"Arbitrum, Optimism, Base, zkSync, Starknet ve Linea yaygın örneklerdir. Çoğu büyük borsa bu ağların bir kısmına doğrudan yatırma ve çekme desteği verir."}],"title":"Layer 2 (L2) nedir? Rollup nasıl çalışır?","description":"Layer 2 ağlarının ne olduğunu, rollup'ların ücretleri nasıl düşürdüğünü ve çekim yaparken doğru ağı nasıl seçeceğinizi öğrenin.","related":[["layer-1","Katman 1 (Layer 1, L1)","Katman 1 (Layer 1, L1), işlemleri kendi başına doğrulayıp kesinleştiren, kendi uzlaşma mekanizmasına ve yerel coinine sahip temel blockchain ağıdır; Bitcoin, Ethereum ve Solana buna örnektir."],["gas-fee","Gas ücreti (gas fee)","Gas ücreti, bir blockchain'de işlem göndermek veya akıllı kontrat çalıştırmak için ağa ödenen ücrettir; Ethereum'da harcanan gas miktarı ile gas fiyatının çarpımı olarak ETH cinsinden hesaplanır."],["cross-chain-bridge","Zincirler arası köprü (cross-chain bridge)","Zincirler arası köprü, bir kripto varlığı bir blokzincirden diğerine taşımanızı sağlayan ve genellikle varlığı kaynak zincirde kilitleyip hedef zincirde bir karşılığını çıkararak çalışan protokoldür."],["ethereum","Ethereum (ETH)","Ethereum, akıllı kontratların çalıştırılabildiği programlanabilir bir blockchain'dir; yerel coini Ether (ETH) hem işlem ücretlerini (gas) ödemek hem de ağı hisse ispatıyla güvence altına almak için kullanılır."],["blockchain-network","Yatırma ağı (ağ seçimi)","Yatırma ağı, bir kripto varlığı transfer ederken işlemin hangi blokzincir üzerinden gideceğini belirleyen seçimdir; gönderen ve alan tarafın aynı ağı desteklemesi gerekir."]],"lesson":null,"coin":{"slug":"arbitrum","name":"Arbitrum","symbol":"ARB"},"tool":null,"cta":false},"spot-trading":{"slug":"spot-trading","cat":"trading","en":"Spot trading","contentLocale":"tr","term":"Spot işlem (spot trading)","aka":["spot","spot piyasa","spot trading","spot alım satım"],"short":"Spot işlem, bir kripto parayı o anki piyasa fiyatından alıp satarak varlığın kendisine anında sahip olduğunuz, kaldıraç ve vade içermeyen temel alım satım türüdür.","body":[["Spot piyasada 100 ",["USDT","usdt"]," ile ",["BTC","bitcoin"]," aldığınızda hesabınıza gerçek BTC geçer. İsterseniz onu cüzdanınıza çekebilir, transfer edebilir veya ",["staking","staking"],"'de kullanabilirsiniz. Vadeli işlemlerde ise varlığın kendisini değil, fiyatına bağlı bir kontratı alırsınız."],["Spot işlemde kaybınız yatırdığınız tutarla sınırlıdır ve ",["likidasyon","liquidation"]," yoktur. Fiyat yüzde 50 düşerse pozisyonunuz yarı değerine iner ama kapanmaz; fiyat toparlanırsa beklemeye devam edebilirsiniz. Bu nedenle spot, yeni başlayanlar için en anlaşılır başlangıç noktasıdır."],["Spot işlemlerde maliyet ücretlerden, alış-satış makasından ve kaymadan oluşur. ",["Limit emir","limit-order"]," kullanmak genellikle daha düşük ",["maker ücreti","maker-taker-fees"]," ödemenizi sağlar. Ücret oranları borsadan borsaya ve işlem hacmi kademesine göre değişir."]],"example":"SOL'ün 150 USDT olduğu bir anda spot piyasada 600 USDT ile 4 SOL aldığınızı varsayalım. Yüzde 0,1 işlem ücreti 0,6 USDT eder. Fiyat 180 USDT'ye çıkarsa 4 SOL 720 USDT olur; satışta yine yaklaşık 0,72 USDT ücret ödersiniz ve net kârınız yaklaşık 118,7 USDT olur. Fiyat 90 USDT'ye düşerse pozisyonunuz 360 USDT'ye iner ama kapanmaz. Aynı hareket 5x kaldıraçlı bir vadeli pozisyonda büyük olasılıkla likidasyonla sonuçlanırdı.","mistakes":["Spot ile vadeli işlem sekmelerini karıştırıp istemeden kaldıraçlı pozisyon açmak.","Düşük likiditeli paritelerde büyük piyasa emirleri verip yüksek kaymaya uğramak.","Ücretleri hesaba katmadan çok sık küçük alım satımlar yapmak."],"faq":[{"q":"Spot işlem ile vadeli işlem arasındaki fark nedir?","a":"Spot işlemde varlığın kendisini alırsınız ve likidasyon yoktur. Vadeli işlemde fiyata bağlı bir kontrat alırsınız, kaldıraç kullanabilirsiniz ve teminatınız yetmezse pozisyon likide edilir."},{"q":"Spot işlemde zarar edilir mi?","a":"Evet, fiyat alış fiyatınızın altına düşer ve satarsanız zarar edersiniz. Ancak kayıp yatırdığınız tutarı aşmaz."}],"title":"Spot işlem nedir? Spot piyasa nasıl çalışır?","description":"Spot işlemin ne olduğunu, vadeli işlemlerden farkını ve neden likidasyon riski taşımadığını örnek hesapla öğrenin.","related":[["trading-pair","İşlem çifti (parite)","İşlem çifti (parite), bir borsada birbirine karşı alınıp satılan iki varlığı gösterir; BTC/USDT paritesinde BTC alınan veya satılan varlık, USDT ise fiyatın ifade edildiği birimdir."],["market-order","Piyasa emri (market order)","Piyasa emri (market order), fiyat belirtmeden verilen ve emir defterindeki en iyi mevcut fiyatlardan hemen gerçekleşen alım veya satım emridir."],["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir."],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"İlk spot işlemin: 100'den 0.002 BTC'ye"},"coin":null,"tool":"/compare","cta":true},"candlestick-chart":{"slug":"candlestick-chart","cat":"trading","en":"Candlestick chart","contentLocale":"tr","term":"Mum grafiği (Candlestick chart)","aka":["mum çubuk grafiği","Japon mumları","candlestick"],"short":"Mum grafiği, her zaman dilimi için açılış, en yüksek, en düşük ve kapanış fiyatını tek bir mum şeklinde gösteren fiyat grafiğidir.","body":["Her mumun bir gövdesi ve iğneleri (fitilleri) vardır. Gövde, açılış ile kapanış arasındaki aralığı gösterir. Kapanış açılıştan yüksekse mum genellikle yeşil, düşükse kırmızı çizilir. Üst iğne dönemin en yüksek, alt iğne ise en düşük fiyatına uzanır.","Zaman dilimini siz seçersiniz: 1 dakikalık, 1 saatlik, 4 saatlik, günlük veya haftalık mumlar. Kısa zaman dilimleri daha çok gürültü içerir. Kripto piyasası 7/24 açık olduğu için günlük mumun açılış ve kapanış saati borsaya ve grafik ayarlarınıza göre değişebilir; birçok platform varsayılan olarak UTC 00:00'ı kullanır.","Uzun bir alt iğne, fiyatın düştükten sonra alıcılar tarafından geri itildiğini; uzun bir üst iğne ise yükselişin satıcılarla karşılandığını gösterir. Mumları hacimle ve destek-direnç seviyeleriyle birlikte okumak, tek bir mumdan sonuç çıkarmaktan daha sağlıklıdır."],"example":["Bir saatlik ",["ETH","ethereum"]," mumu 3.000 ",["USDT","usdt"],"'den açılıyor, saat içinde 3.080'e çıkıyor, 2.970'e iniyor ve 3.050'den kapanıyor. Kapanış açılıştan yüksek olduğu için mum yeşildir. Gövde 3.000 ile 3.050 arasında, yani 50 USDT boyundadır. Üst iğne 3.050'den 3.080'e 30 USDT, alt iğne 3.000'den 2.970'e 30 USDT uzanır. Saatlik toplam aralık 110 USDT, yani açılış fiyatına göre yaklaşık yüzde 3,7'dir."],"mistakes":["Tek bir mum formasyonunu kesin al-sat sinyali gibi kullanmak.","Henüz kapanmamış bir mumu kapanmış gibi yorumlamak; mum kapanana kadar şekli değişebilir.","Farklı zaman dilimlerindeki mumları karıştırıp birbiriyle çelişen sonuçlar çıkarmak."],"faq":[{"q":"Yeşil ve kırmızı mum ne anlama gelir?","a":"Yeşil mum kapanışın açılıştan yüksek, kırmızı mum ise düşük olduğunu gösterir. Bazı uygulamalarda bu renkler ayarlardan değiştirilebilir."},{"q":"Mum grafiği hangi zaman diliminde okunmalı?","a":"İşlem tarzınıza bağlıdır. Uzun vadeli yatırımcılar genelde günlük ve haftalık, kısa vadeli işlemciler ise 15 dakika ile 4 saat arası mumlara bakar."}],"title":"Mum grafiği nedir? Kripto mumları nasıl okunur","description":"Mum grafiğinde gövde, iğne, renk ve zaman diliminin ne anlama geldiğini örnek bir ETH mumuyla öğrenin.","related":[["support-and-resistance","Destek ve direnç (Support and resistance)","Destek ve direnç, grafikte fiyatın daha önce düşüşünün (destek) veya yükselişinin (direnç) durduğu ve alıcılarla satıcıların yoğunlaştığı fiyat bölgeleridir."],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir."],["trading-volume","İşlem hacmi (Trading volume)","İşlem hacmi, belirli bir sürede, genellikle 24 saatte, bir varlığın ne kadarının alınıp satıldığını gösteren toplam miktardır."],["all-time-high","Tüm zamanların en yüksek seviyesi (ATH)","Tüm zamanların en yüksek seviyesi (all-time high, ATH), bir kripto paranın işlem görmeye başladığından bu yana ulaştığı en yüksek fiyattır."]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"Tek bir mum: Size söylediği dört şey nedir?"},"coin":null,"tool":null,"cta":false},"last-price":{"slug":"last-price","cat":"derivatives","en":"Last traded price","contentLocale":"tr","term":"Son işlem fiyatı (Last traded price)","aka":["son fiyat","last price","son işlem"],"short":"Son işlem fiyatı, bir borsadaki belirli bir paritede veya kontratta en son gerçekleşen alım-satım işleminin fiyatıdır.","body":["Uygulamada büyük harflerle gördüğünüz fiyat genellikle son işlem fiyatıdır. Bu, bir alıcı ile satıcının en son eşleştiği fiyattır; o anda sizin alabileceğiniz veya satabileceğiniz fiyatla aynı olmak zorunda değildir. Gerçekte alım için en iyi satış emrine, satış için en iyi alış emrine bakmanız gerekir.",["Likit piyasalarda son fiyat, en iyi alış ve satış fiyatlarının çok yakınındadır. İnce piyasalarda ise son işlem dakikalar önce gerçekleşmiş olabilir ve ",["emir defteri","order-book"]," o fiyattan çok uzaklaşmış olabilir. Ayrıca tek bir büyük emir son fiyatı anlık olarak kaydırarak grafikte bir iğne oluşturabilir."],["Vadeli işlemlerde ",["likidasyon","liquidation"]," için genellikle son fiyat değil işaret fiyatı kullanılır. Stop ve kâr al emirlerinde ise birçok borsa tetikleyici olarak son fiyatı varsayılan yapar; bunu emir ekranında değiştirebilirsiniz."]],"example":["Bir altcoinin son işlem fiyatı ekranda 0,500 ",["USDT","usdt"]," görünüyor. Emir defterinde ise en iyi alış 0,492, en iyi satış 0,508 USDT. Hemen 1.000 coin almak isterseniz en az 0,508'den, yani yaklaşık 508 USDT ödersiniz. Hemen satmak isterseniz en fazla 0,492'den 492 USDT alırsınız. Son fiyata göre beklediğiniz 500 USDT'lik değer, her iki yönde de yaklaşık yüzde 1,6 sapma gösterir."],"mistakes":["Son fiyatı, piyasa emrinizin gerçekleşeceği fiyat sanmak.","Vadeli işlemlerde likidasyonun son fiyata göre olduğunu düşünmek.","Stop emrinin tetikleyicisini kontrol etmeden son fiyattaki bir iğneyle stop olmak."],"faq":[{"q":"Son fiyat ile işaret fiyatı arasındaki fark nedir?","a":"Son fiyat o kontratta gerçekleşen son işlemdir. İşaret fiyatı ise birden fazla spot borsaya dayanan, likidasyon ve kâr-zarar hesabı için kullanılan daha istikrarlı bir fiyattır."},{"q":"Neden son fiyattan alım yapamadım?","a":"Son fiyat geçmişte gerçekleşmiş bir işlemdir. Alım yaparken defterdeki mevcut satış emirlerinden doldurulursunuz ve bu fiyat son fiyattan farklı olabilir."}],"title":"Son işlem fiyatı (last price) nedir?","description":"Son işlem fiyatının ne olduğunu, alış-satış fiyatından ve işaret fiyatından neden farklı olabileceğini öğrenin.","related":[["mark-price","İşaret fiyatı (Mark price)","İşaret fiyatı (mark price), vadeli işlem borsalarının gerçekleşmemiş kâr-zararı ve likidasyonu hesaplamak için kullandığı, manipülasyona karşı dengelenmiş adil fiyattır."],["index-price","Endeks fiyatı (Index price)","Endeks fiyatı, bir varlığın birden fazla büyük spot borsadaki fiyatlarının ağırlıklı ortalamasından hesaplanan ve vadeli kontratlar için referans olarak kullanılan fiyattır."],["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir."],["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Ekrandaki fiyat neden benim gerçekleşen fiyatım değil?"},"coin":null,"tool":null,"cta":false},"funding-rate-arbitrage":{"slug":"funding-rate-arbitrage","cat":"derivatives","en":"Funding rate arbitrage","contentLocale":"tr","term":"Fonlama oranı arbitrajı (Funding rate arbitrage)","aka":["funding arbitrajı","fonlama arbitrajı","delta nötr fonlama stratejisi"],"short":"Fonlama oranı arbitrajı, spot piyasada bir coin alıp aynı miktarda perpetual short açarak fiyat riskini nötrlediğiniz ve pozitif fonlama ödemelerini topladığınız stratejidir.","body":[[["Fonlama oranı","funding-rate"]," pozitifken long tarafı short tarafına ödeme yapar. Spot 1 ",["BTC","bitcoin"]," alıp ",["perpetual","perpetual-futures"]," kontratta 1 BTC short açarsanız, fiyat hareketi iki bacakta birbirini götürür ve siz düzenli olarak fonlama ödemesi alırsınız. Bu yapıya delta nötr pozisyon denir."],"Strateji risksiz değildir. Fonlama negatife dönerse bu kez siz ödersiniz. Fiyat sert yükselirse short bacakta teminat ihtiyacı artar; yeterli teminat yoksa short tasfiye olur ve spot bacak korumasız kalır. Ayrıca giriş ve çıkış ücretleri, spot ile vadeli arasındaki baz değişimleri ve borsa riski getiriyi azaltır.",["Bazı işlemciler aynı coinde iki borsa arasındaki fonlama farkından yararlanmak için bir borsada long, diğerinde short açar. ",["Birleşik hesap","unified-trading-account"]," sunan borsalarda spot varlığın short için teminat olarak sayılması strateji için teminat verimliliğini artırabilir; kurallar borsaya göre değişir."]],"example":[["ETH","ethereum"]," 3.200 ",["USDT","usdt"]," iken 5 ETH spot alıyor ve 5 ETH perpetual short açıyorsunuz; her bacak 16.000 USDT. Fonlama oranı 8 saatte bir ortalama yüzde 0,01 olursa her ödemede 1,6 USDT, günde 4,8 USDT alırsınız. 30 günde toplam 144 USDT eder. Giriş ve çıkışta dört işlem için yüzde 0,05'ten toplam yaklaşık 32 USDT ücret düşülünce net yaklaşık 112 USDT kalır; bu, spot bacağa göre yaklaşık yüzde 0,7'lik aylık getiri demektir."],"mistakes":["Fonlama oranının sürekli pozitif kalacağını varsayıp negatife döndüğünü takip etmemek.","Short bacağa yetersiz teminat koyup sert yükselişte tasfiye olmak.","Giriş-çıkış ücretlerini hesaba katmadan kısa süreli yüksek fonlamayı kovalamak."],"faq":[{"q":"Fonlama oranı arbitrajı risksiz mi?","a":"Hayır. Fonlama yön değiştirebilir, short bacak tasfiye olabilir ve borsa riski devam eder. Fiyat riski büyük ölçüde nötrlenir, ama diğer riskler kalır."},{"q":"Fonlama arbitrajı için ne kadar teminat gerekir?","a":"Short bacağın sert yükselişlerde tasfiye olmayacağı kadar teminat gerekir. Birçok işlemci bu bacakta düşük kaldıraç kullanır."}],"title":"Fonlama oranı arbitrajı nedir? Nasıl yapılır","description":"Spot alım ve perpetual short ile fonlama oranı arbitrajının nasıl kurulduğunu, getirisini ve risklerini öğrenin.","related":[["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."],["arbitrage","Arbitraj (Arbitrage)","Arbitraj, aynı varlığın farklı piyasalardaki fiyat farkından yararlanmak için ucuz olduğu yerden alıp pahalı olduğu yerde satma işlemidir."],["hedging","Hedge (Riskten korunma)","Hedge (riskten korunma), mevcut bir pozisyonun olası kaybını azaltmak için ters yönde ve onunla ilişkili ikinci bir pozisyon açma stratejisidir."],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"Fiyat sabit, bakiye düştü mü? Maliyetleri unutmadan son aşamayı tamamlayın"},"coin":null,"tool":"/funding-rates","cta":false},"hardware-wallet":{"slug":"hardware-wallet","cat":"wallets-security","en":"Hardware wallet","contentLocale":"tr","term":"Donanım cüzdanı (hardware wallet)","aka":["hardware wallet","donanımsal cüzdan","fiziksel cüzdan"],"short":"Donanım cüzdanı, özel anahtarları güvenli bir çip içinde çevrim dışı saklayan ve işlemleri cihazın kendi ekranında onaylatarak imzalayan küçük bir fiziksel cihazdır.","body":["Ledger, Trezor gibi markaların ürettiği bu cihazlar USB, Bluetooth veya QR kod üzerinden bir uygulamayla konuşur. Bilgisayar ya da telefon yalnızca işlemi hazırlar; imza cihazın içinde atılır ve anahtar dışarı hiç çıkmaz.","En önemli güvenlik özelliği cihaz ekranıdır. Bilgisayarınızda bir zararlı yazılım alıcı adresini değiştirse bile, doğru adresi ve tutarı cihaz ekranında görüp kontrol edebilirsiniz. PIN kodu da cihazı fiziksel olarak çalan birinin işlem yapmasını zorlaştırır.","Cihaz kaybolursa veya bozulursa fonlar kaybolmaz; kurulum sırasında verilen kurtarma ifadesiyle aynı cüzdanı yeni bir cihazda geri yükleyebilirsiniz. Asıl risk, bu ifadenin başkasının eline geçmesi veya cihazın güvenilmeyen bir satıcıdan alınmasıdır."],"example":["Bir donanım cüzdanıyla borsaya 1.500 ",["USDT","usdt"]," göndermek istediğinizi varsayalım. Uygulamada borsa adresinizi yapıştırırsınız; adres 0x9A3f ile başlayıp 7C21 ile bitiyor. Cihaz ekranında ise 0x9A3f ile başlayıp 4B88 ile biten bir adres görürseniz bilgisayarınızda adres değiştiren bir zararlı olabilir. Onaylamazsınız ve 1.500 USDT cüzdanınızda kalır. Adresler eşleşiyorsa ve ",["ağ ücreti","gas-fee"]," örneğin 1 USDT ise işlemi onaylarsınız."],"mistakes":["Cihazı ikinci el pazarlardan veya resmî olmayan satıcılardan almak.","Kutudan önceden yazılmış bir kurtarma ifadesi çıkarsa onu kullanmak; gerçek cihaz ifadeyi kurulumda kendisi üretir.","Cihaz ekranını okumadan her işlemi otomatik olarak onaylamak."],"faq":[{"q":"Donanım cüzdanı kaybolursa ne olur?","a":"Kurtarma ifadeniz güvendeyse yeni bir cihaza veya uyumlu bir cüzdana geri yükleyerek aynı fonlara erişirsiniz. PIN, bulan kişinin cihazı kullanmasını zorlaştırır."},{"q":"Donanım cüzdanı hacklenebilir mi?","a":"Uzaktan anahtar çalmak çok zordur, ancak kullanıcıyı kötü bir işlemi onaylamaya ikna etmek veya kurtarma ifadesini ele geçirmek mümkündür. Risk çoğunlukla cihazdan değil kullanım alışkanlıklarından gelir."}],"title":"Donanım cüzdanı nedir? Hardware wallet nasıl çalışır?","description":"Donanım cüzdanının anahtarları nasıl koruduğunu, cihaz ekranında neyi kontrol etmeniz gerektiğini ve yaygın hataları öğrenin.","related":[["cold-wallet","Soğuk cüzdan (cold wallet)","Soğuk cüzdan, özel anahtarları internete hiç bağlanmayan bir cihazda veya ortamda saklayarak uzaktan çalınma riskini büyük ölçüde azaltan kripto saklama yöntemidir."],["seed-phrase","Kurtarma ifadesi (seed phrase)","Kurtarma ifadesi (seed phrase), bir kripto cüzdanının tüm özel anahtarlarının türetildiği 12 veya 24 kelimelik listedir ve bu kelimeleri bilen herkes cüzdanın tamamını kontrol edebilir."],["private-key","Özel anahtar (private key)","Özel anahtar, bir kripto adresindeki varlıkları harcamak için gereken dijital imzayı üreten gizli bir sayıdır ve onu bilen kişi o adresin fiilî sahibi olur."],["address-poisoning","Adres zehirleme (address poisoning)","Adres zehirleme, dolandırıcının sizin sık kullandığınız adrese benzeyen bir adresten işlem geçmişinize küçük veya sıfır tutarlı transferler göndererek, bir sonraki transferinizde yanlış adresi kopyalamanızı sağlamaya çalıştığı saldırıdır."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı"},"coin":null,"tool":null,"cta":false},"governance-token":{"slug":"governance-token","cat":"defi","en":"Governance token","contentLocale":"tr","term":"Yönetişim token'ı (governance token)","aka":["governance token","yönetim token'ı","oy token'ı"],"short":"Yönetişim token'ı, sahiplerine bir protokolün veya DAO'nun kararlarında oy kullanma hakkı veren kripto token'ıdır; örneğin UNI, Uniswap yönetişiminde kullanılır.","body":["Yönetişim token'ları ile ücret oranları, desteklenen varlıklar, hazine harcamaları ve protokol yükseltmeleri gibi konularda oy kullanılır. Genellikle bir token bir oy anlamına gelir. Birçok protokol oy hakkını delegelere devretmenize izin verir; böylece aktif olarak takip etmeseniz de oyunuz kullanılabilir.",["Bu token'lar çoğu zaman ",["airdrop","airdrop"],", ",["likidite madenciliği","yield-farming"]," veya satış yoluyla dağıtılır. Bir kısmı genellikle ekip ve yatırımcılar için ayrılır ve kilit açılış takvimine (vesting) bağlıdır. Büyük kilit açılışları piyasaya ek arz getirebilir."],["Yönetişim token'ı otomatik olarak gelir payı veya hisse hakkı vermez. Bazı protokoller ücret paylaşımı veya geri alım mekanizmaları ekler, bazıları eklemez. Token'ın değeri; protokolün kullanımına, token ekonomisine (",["tokenomics","tokenomics"],") ve piyasa beklentilerine bağlıdır. Ayrıca bazı ülkelerde bu tür token'ların hukuki niteliği tartışmalıdır."]],"example":"Bir protokolün toplam 1 milyar yönetişim token'ı olduğunu ve bunun yüzde 40'ının ekip ile yatırımcılara ayrıldığını varsayalım. Siz 5.000 token tutuyorsunuz; bu toplam arzın yüzde 0,0005'i. Bir ücret değişikliği oylamasında ekip ve fonların yalnızca yüzde 5'lik kısmı, yani 20 milyon token oy kullansa, bu sizin oyunuzdan 4.000 kat ağırdır. Gücünüzü artırmak için oyunuzu sizinle aynı görüşteki bir delegeye devredebilirsiniz.","mistakes":["Yönetişim token'ını şirket hissesiyle karıştırmak.","Kilit açılış takvimini ve arz dağılımını kontrol etmemek.","Oy hakkını hiç kullanmadan token'ın tüm değerini yönetişime bağlamak."],"faq":[{"q":"Yönetişim token'ı temettü öder mi?","a":"Genellikle hayır. Bazı protokoller ücret paylaşımı veya geri alım uygular, ancak bu her token için geçerli değildir ve kurallar zamanla değişebilir."},{"q":"Oy kullanmak için token'ı stake etmem gerekir mi?","a":"Protokole göre değişir. Bazılarında token'ı cüzdanda tutup delege etmek yeterlidir, bazılarında kilitleme gerekir."}],"title":"Yönetişim token'ı nedir? Governance token ne işe yarar?","description":"Yönetişim token'larının oy hakkını nasıl sağladığını, dağıtım ve kilit açılış yapılarını ve gerçek değerini neyin belirlediğini öğrenin.","related":[["dao","DAO (merkeziyetsiz otonom organizasyon)","DAO, kurallarının akıllı sözleşmelerle tanımlandığı ve kararlarının genellikle yönetişim token'ı sahiplerinin oylarıyla alındığı, yöneticisi tek bir şirket olmayan internet tabanlı bir organizasyondur."],["tokenomics","Tokenomik (tokenomics)","Tokenomik (tokenomics), bir token'ın toplam arzını, dağıtımını, kilit açılma takvimini, kullanım alanlarını ve arzı artıran ya da azaltan mekanizmaları kapsayan ekonomik tasarımıdır."],["airdrop","Airdrop","Airdrop, bir projenin token'larını belirli koşulları sağlayan cüzdanlara veya kullanıcılara ücretsiz olarak dağıtmasıdır; genellikle erken kullanıcıları ödüllendirmek ve token'ı geniş bir kitleye yaymak amacıyla yapılır."],["coin-vs-token","Coin ve token farkı","Coin, kendi blockchain'inin yerel varlığıdır (BTC, ETH, SOL gibi); token ise başka bir blockchain üzerinde akıllı kontratla oluşturulan varlıktır (Ethereum üzerindeki USDT veya UNI gibi)."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"usdt":{"slug":"usdt","cat":"stablecoins","en":"USDT (Tether)","contentLocale":"tr","term":"USDT (Tether)","aka":["Tether","USDT","tether coin"],"short":"USDT (Tether), Tether şirketi tarafından çıkarılan, değerini 1 ABD dolarına sabitlemeyi amaçlayan ve kripto piyasalarında en yaygın kullanılan stablecoin'dir.","body":["Tether, her USDT'nin nakit, kısa vadeli ABD hazine bonoları ve diğer varlıklardan oluşan rezervlerle desteklendiğini belirtir ve düzenli rezerv raporları (attestation) yayınlar. Bu raporlar tam kapsamlı bir bağımsız denetimle aynı şey değildir; rezerv şeffaflığı yıllardır tartışma konusudur.",["USDT birçok blokzincirde çıkarılmıştır: ",["Ethereum","ethereum"]," (ERC20), Tron (TRC20), BNB Smart Chain, Solana, TON ve diğerleri. Farklı ağlardaki USDT aynı token'ın farklı versiyonlarıdır ve birbirinin yerine doğrudan gönderilemez. Transfer yaparken alıcının hangi ağı desteklediğini kontrol etmek önemlidir."],["USDT, borsalarda en derin işlem çiftlerinin karşı varlığıdır ve ",["P2P","p2p-trading"]," piyasalarında yerel paralarla alınıp satılır. Türkiye'de de kullanıcıların TL ile kriptoya geçişte sıkça kullandığı ",["stablecoin","stablecoin"],"'dir. Tether gerektiğinde belirli adreslerdeki USDT'yi dondurabilir; bu, stablecoin'in merkezi yapısını gösteren önemli bir özelliktir. Avrupa'da ",["MiCA","mica"]," kuralları nedeniyle bazı borsalar AB kullanıcıları için USDT erişimini sınırlamıştır."]],"example":["Bir borsadaki 500 USDT'yi başka bir borsaya göndermek istiyorsunuz. Alıcı borsa ERC20 ve TRC20 ağlarını kabul ediyor. ERC20 ",["çekim ücreti","withdrawal-fee"]," örneğin 3 USDT, TRC20 ücreti 1 USDT ise TRC20 seçip 499 USDT ulaştırabilirsiniz. Adresi alıcı borsanın TRC20 yatırma sayfasından kopyalarsınız; bu adres T ile başlar. ERC20 seçip T ile başlayan bir adres girmeye çalışırsanız sistem büyük ihtimalle adresi reddeder."],"mistakes":["Farklı ağlardaki USDT'nin birbirine otomatik olarak dönüştüğünü sanmak.","P2P işlemlerde ödeme dekontuna bakmadan USDT'yi serbest bırakmak.","USDT'nin dolar ile birebir aynı yasal güvenceye sahip olduğunu düşünmek."],"faq":[{"q":"USDT güvenli mi?","a":"Uzun süredir 1 dolara yakın işlem görür ve en likit stablecoin'dir. Yine de ihraççı riski, rezerv şeffaflığı tartışmaları ve dondurma yetkisi gibi riskleri vardır."},{"q":"TRC20 ve ERC20 USDT arasındaki fark nedir?","a":"Değer aynıdır ama farklı blokzincirlerde çalışırlar. Ücret, hız ve alıcının hangi ağı desteklediği farklıdır."}],"title":"USDT (Tether) nedir? Nasıl çalışır ve hangi ağlarda var?","description":"USDT'nin nasıl desteklendiğini, ERC20 ve TRC20 gibi ağlar arasındaki farkları ve kullanırken nelere dikkat edeceğinizi öğrenin.","related":[["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["usdc","USDC (USD Coin)","USDC (USD Coin), Circle tarafından çıkarılan, nakit ve kısa vadeli ABD hazine bonolarıyla desteklenen ve değerini 1 ABD dolarına sabitlemeyi amaçlayan bir stablecoin'dir."],["blockchain-network","Yatırma ağı (ağ seçimi)","Yatırma ağı, bir kripto varlığı transfer ederken işlemin hangi blokzincir üzerinden gideceğini belirleyen seçimdir; gönderen ve alan tarafın aynı ağı desteklemesi gerekir."],["depeg","Depeg (sabitin kopması)","Depeg, bir stablecoin'in bağlı olduğu değerden, örneğin 1 dolardan, belirgin ve kalıcı biçimde uzaklaşmasıdır; coin artık hedef fiyatında işlem görmez."],["p2p-trading","P2P alım satım (C2C)","P2P alım satım, kullanıcıların borsanın aracılık ettiği bir pazarda, kripto varlığı birbirlerinden banka transferi gibi ödeme yöntemleriyle doğrudan aldığı veya sattığı işlem türüdür."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT dolar mı? Kripto alırken neden her yerde karşımıza çıkar?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"synthetic-dollar":{"slug":"synthetic-dollar","cat":"stablecoins","en":"Synthetic dollar (delta-neutral stablecoin)","contentLocale":"tr","term":"Sentetik dolar (delta nötr stablecoin)","aka":["sentetik dolar","synthetic dollar","delta nötr stablecoin","USDe"],"short":"Sentetik dolar, spot kripto varlığı tutup aynı büyüklükte short vadeli pozisyon açarak fiyat riskini sıfırlayan ve böylece yaklaşık 1 dolar değerinde kalmayı hedefleyen token'dır.","body":[["Bu modelde ",["stablecoin","stablecoin"],"'in arkasında banka rezervi yoktur. Protokol, örneğin ",["ETH","ethereum"]," tutar ve aynı miktarda ETH sürekli (",["perpetual","perpetual-futures"],") vadeli kontratta short açar. ETH yükselirse spot kazanır, short kaybeder; düşerse tam tersi olur. Toplam değer kabaca sabit kalır. Buna delta nötr pozisyon denir. Bilinen örnek Ethena'nın USDe token'ıdır."],["Getirinin büyük kısmı fonlama oranından gelir. Piyasa genellikle long tarafta kalabalık olduğunda ",["fonlama oranı","funding-rate"]," pozitiftir ve short taraf ödeme alır. Ayrıca stake edilmiş ETH kullanılırsa ",["staking","staking"]," getirisi eklenir."],["Riskler farklıdır: fonlama oranı uzun süre negatif kalırsa getiri eksiye döner; pozisyonların tutulduğu borsalarda sorun yaşanabilir; büyük çıkışlarda ",["hedge","hedging"]," pozisyonlarını kapatmak zorlaşabilir. Yani bu bir banka mevduatı değil, aktif yönetilen bir stratejidir."]],"example":"Bir protokolün 1.000.000 dolarlık ETH tuttuğunu ve aynı büyüklükte short açtığını düşünelim. ETH yüzde 10 düşerse spot 100.000 dolar kaybeder, short 100.000 dolar kazanır; toplam yine 1.000.000 dolar. Fonlama oranı 8 saatte bir yüzde 0,01 ise short taraf her ödemede 100 dolar alır, günde 3 ödemeyle 300 dolar eder. Bu yıllık yaklaşık yüzde 11 getiriye denk gelir. Oran yüzde -0,01'e dönerse protokol aynı tutarı öder ve getiri eksiye geçer.","mistakes":["Sentetik doları rezervli bir stablecoin ile aynı risk seviyesinde görmek.","Geçmiş getiriyi sabit faiz sanmak; getiri fonlama oranına göre sürekli değişir.","Negatif fonlama dönemlerinde ve borsa riskinde ne olacağını sorgulamamak."],"faq":[{"q":"USDe nasıl 1 dolarda kalıyor?","a":"USDe, teminat olarak tuttuğu kripto varlığa karşı vadeli piyasada short pozisyon açarak fiyat riskini dengeler. Böylece toplam değer kabaca 1 dolar civarında kalır."},{"q":"Sentetik doların getirisi nereden gelir?","a":"Getiri çoğunlukla short pozisyonlara ödenen pozitif fonlama oranından ve varsa staking ödüllerinden gelir. Fonlama negatife döndüğünde getiri düşer veya eksiye geçer."}],"title":"Sentetik dolar nedir? Delta nötr stablecoin rehberi","description":"Sentetik dolar ve delta nötr stablecoin nasıl çalışır, getiri fonlama oranından nasıl gelir ve hangi riskleri taşır, öğrenin.","related":[["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."],["hedging","Hedge (Riskten korunma)","Hedge (riskten korunma), mevcut bir pozisyonun olası kaybını azaltmak için ters yönde ve onunla ilişkili ikinci bir pozisyon açma stratejisidir."],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["depeg","Depeg (sabitin kopması)","Depeg, bir stablecoin'in bağlı olduğu değerden, örneğin 1 dolardan, belirgin ve kalıcı biçimde uzaklaşmasıdır; coin artık hedef fiyatında işlem görmez."]],"lesson":null,"coin":{"slug":"ethena-usde","name":"Ethena USDe","symbol":"USDE"},"tool":"/funding-rates","cta":false}});
